#include "../inc/Timer.h"


// globals that track current sound state
const uint8_t *soundPointer;
uint32_t soundCounter;


void SysTick_IntArm(uint32_t period, uint32_t priority){
  // write this
  SysTick->CTRL = 0;                // disable SysTick during setup
  SysTick->LOAD = period - 1;       // set reload value
  SysTick->VAL = 0;                 // clear current value
  SCB->SHP[1] = priority << 5;     // set priority
  SysTick->CTRL = 0x07;             // enable SysTick, enable interrupt, use CPU clock  
}
// initialize a 11kHz SysTick, however no sound should be started
// initialize any global variables
// Initialize the 5-bit DAC
void Sound_Init(void){
// write this
  DAC5_Init();                          // initialize the 5-bit DAC
  soundPointer = 0;                     // no sound playing yet
  soundCounter = 0;                     // no samples remaining
  SysTick_IntArm(80000000/11000, 2);    // arm at 11kHz, priority 2  
}

void SysTick_Handler(void){ // called at 11 kHz
  // output one value to DAC if a sound is active
    // output one value to DAC if a sound is active
  if (soundCounter > 0) {
    DAC5_Out(*soundPointer);   // output current sample to DAC
    soundPointer++;            // advance to next sample
    soundCounter--;            // one fewer sample remaining
  }
}

//******* Sound_Start ************
// This function does not output to the DAC. 
// Rather, it sets a pointer and counter, and then enables the SysTick interrupt.
// It starts the sound, and the SysTick ISR does the output
// feel free to change the parameters
// Sound should play once and stop
// Input: pt is a pointer to an array of DAC outputs
//        count is the length of the array
// Output: none
// special cases: as you wish to implement
void Sound_Start(const uint8_t *pt, uint32_t count){
// write this
soundPointer = pt;     // point to start of sound array
soundCounter = count;  // set number of samples to play
}



void Sound_Shoot(void){
// write this
  Sound_Start( shoot, 4080);
}

